// Chrome's UA stylesheet for `<input>` is per TYPE, and chrome_per_tag_values
// is per tag.
//
// That file is generated by measuring one bare element of each tag, so its
// `input` row is the text field's and every other type inherited it: a checkbox
// carried the text field's 1px/2px of padding inside a 2px inset border and
// came out 149x17 where Chrome's is 13x13. Fourteen distinct box shapes across
// the twenty-two types were all one shape here.
//
// Hand-authored rather than generated, because the generator's unit is the tag.
// Teaching dump-css-initial-values.mjs to sweep `input[type]` as well would
// fold this back into the generated table and is the right eventual home for
// it. Until then these are measured, not reasoned about: Chrome 151, with
// tools/fingerprint/scratch/b84-typeedge.js for the edges and b84-typebox.js
// for the boxes.
//
// Only the names that DIFFER from the text field's row are listed. A type with
// no entry here, and any name a listed type does not override, falls through to
// the `input` row in chrome_per_tag_values, which is what the text family
// wants.

const std = @import("std");

const Values = std.StaticStringMap([]const u8);

/// The edges shared by every type that draws no chrome of its own: the
/// checkbox, the radio, the range slider, the file picker and the image button
/// have no padding and no border at all.
const no_edges = .{
    .{ "padding-top", "0px" },          .{ "padding-right", "0px" },
    .{ "padding-bottom", "0px" },       .{ "padding-left", "0px" },
    .{ "padding", "0px" },              .{ "padding-block", "0px" },
    .{ "padding-inline", "0px" },       .{ "border-top-width", "0px" },
    .{ "border-right-width", "0px" },   .{ "border-bottom-width", "0px" },
    .{ "border-left-width", "0px" },    .{ "border-width", "0px" },
    .{ "border-top-style", "none" },    .{ "border-right-style", "none" },
    .{ "border-bottom-style", "none" }, .{ "border-left-style", "none" },
    .{ "border-style", "none" },
};

/// The three buttons: `submit`, `reset` and `button`. Wider padding than the
/// text field, an outset border rather than an inset one, and a border box.
const button_edges = .{
    .{ "padding-top", "1px" },           .{ "padding-right", "6px" },
    .{ "padding-bottom", "1px" },        .{ "padding-left", "6px" },
    .{ "padding", "1px 6px" },           .{ "border-top-style", "outset" },
    .{ "border-right-style", "outset" }, .{ "border-bottom-style", "outset" },
    .{ "border-left-style", "outset" },  .{ "border-style", "outset" },
    .{ "box-sizing", "border-box" },
};

/// The date family -- `date`, `datetime-local`, `month`, `week` and `time` --
/// keeps the text field's 2px inset border but drops every padding except a
/// single pixel on the left.
const date_edges = .{
    .{ "padding-top", "0px" },         .{ "padding-right", "0px" },
    .{ "padding-bottom", "0px" },      .{ "padding-left", "1px" },
    .{ "padding", "0px 0px 0px 1px" },
};

/// lowercase `type` -> the longhands that differ from the text field's row.
pub const per_type = blk: {
    @setEvalBranchQuota(20000);
    break :blk std.StaticStringMap(Values).initComptime(.{
        .{ "checkbox", Values.initComptime(no_edges ++ .{.{ "box-sizing", "border-box" }}) },
        .{ "radio", Values.initComptime(no_edges ++ .{.{ "box-sizing", "border-box" }}) },
        .{ "range", Values.initComptime(no_edges) },
        .{ "file", Values.initComptime(no_edges) },
        .{ "image", Values.initComptime(no_edges) },
        // The colour well is the odd one: it keeps the text field's padding but
        // draws a 1px SOLID border rather than a 2px inset one, and sizes as a
        // border box.
        .{ "color", Values.initComptime(.{
            .{ "border-top-width", "1px" },     .{ "border-right-width", "1px" },
            .{ "border-bottom-width", "1px" },  .{ "border-left-width", "1px" },
            .{ "border-width", "1px" },         .{ "border-top-style", "solid" },
            .{ "border-right-style", "solid" }, .{ "border-bottom-style", "solid" },
            .{ "border-left-style", "solid" },  .{ "border-style", "solid" },
            .{ "box-sizing", "border-box" },
        }) },
        .{ "submit", Values.initComptime(button_edges) },
        .{ "reset", Values.initComptime(button_edges) },
        .{ "button", Values.initComptime(button_edges) },
        .{ "date", Values.initComptime(date_edges) },
        .{ "datetime-local", Values.initComptime(date_edges) },
        .{ "month", Values.initComptime(date_edges) },
        .{ "week", Values.initComptime(date_edges) },
        .{ "time", Values.initComptime(date_edges) },
    });
};

/// The UA value this input type gives `name`, or null where the type overrides
/// nothing by that name and the text field's row should answer.
pub fn get(input_type: []const u8, name: []const u8) ?[]const u8 {
    const rows = per_type.get(input_type) orelse return null;
    return rows.get(name);
}
